UPDATE public.orders o SET invoice_state=CASE WHEN document_status='cancelled' THEN 'cancelled' ELSE 'issued' END,issued_at=o.created_at,order_date=COALESCE(o.invoice_date,(o.created_at AT TIME ZONE 'Asia/Jakarta')::date),brand_snapshot=(SELECT to_jsonb(s)||jsonb_build_object('name',t.name) FROM public.tenant_settings s JOIN public.tenants t ON t.id=s.tenant_id WHERE s.tenant_id=o.tenant_id),discount_value=o.discount_pct WHERE o.invoice_number IS NOT NULL AND o.issued_at IS NULL AND o.document_status IN ('final','cancelled');
INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) SELECT tenant_id,regexp_replace(upper(client_name),'[^A-Z0-9]','','g'),'invoice',max((regexp_match(invoice_number,'/([0-9]+)$'))[1]::bigint) FROM public.orders WHERE invoice_number ~ '^INV/[^/]+/[0-9]{4}/[0-9]{2}/[0-9]+$' GROUP BY tenant_id,regexp_replace(upper(client_name),'[^A-Z0-9]','','g') ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,EXCLUDED.sequence);
CREATE TRIGGER quotation_tenant_guard BEFORE INSERT OR UPDATE OR DELETE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.guard_business_row();
CREATE TRIGGER quotation_item_tenant_guard BEFORE INSERT OR UPDATE OR DELETE ON public.quotation_items FOR EACH ROW EXECUTE FUNCTION public.guard_business_row();
CREATE FUNCTION public.quotation_archive_children() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at AND NEW.deleted_at IS NOT NULL THEN UPDATE public.quotation_items SET deleted_at=NEW.deleted_at,deleted_by=NEW.deleted_by,delete_reason=NEW.delete_reason WHERE tenant_id=NEW.tenant_id AND quotation_id=NEW.id AND deleted_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER quotation_archive_children AFTER UPDATE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.quotation_archive_children();
CREATE OR REPLACE FUNCTION public.linked_receivable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.order_id IS NOT NULL OR (TG_OP='UPDATE' AND OLD.order_id IS NOT NULL)) THEN IF current_user NOT IN ('postgres','supabase_admin','service_role') THEN RAISE EXCEPTION 'Piutang invoice mengikuti catatan pembayaran'; END IF; IF TG_OP='UPDATE' AND NEW.deleted_at IS DISTINCT FROM OLD.deleted_at AND NEW.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Piutang terkait invoice tidak boleh diarsipkan langsung'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.finance_invoice_balances() RETURNS TABLE(order_id uuid,invoice_number text,client_name text,invoice_state text,total numeric,paid numeric,balance numeric,status text,due_date date) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; t jsonb; BEGIN IF NOT public.can_access('finance') THEN RAISE EXCEPTION 'Finance tidak berizin'; END IF; FOR o IN SELECT * FROM public.orders WHERE tenant_id=public.active_tenant_id() AND deleted_at IS NULL AND invoice_state IN ('issued','cancelled') LOOP t:=public.sales_totals('orders',o.id); order_id:=o.id;invoice_number:=o.invoice_number;client_name:=o.client_name;invoice_state:=o.invoice_state;total:=(t->>'total')::numeric;paid:=(t->>'paid')::numeric;balance:=CASE WHEN o.invoice_state='cancelled' THEN 0 ELSE (t->>'balance')::numeric END;status:=t->>'state';due_date:=o.due_date;RETURN NEXT; END LOOP; END $$;
GRANT EXECUTE ON FUNCTION public.finance_invoice_balances() TO authenticated; REVOKE EXECUTE ON FUNCTION public.finance_invoice_balances() FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.set_quotation_status(p_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quotations; totals jsonb; threshold numeric; BEGIN IF NOT public.can_access('quotations') OR p_status NOT IN ('draft','terkirim','disetujui','ditolak','kedaluwarsa') THEN RAISE EXCEPTION 'Tidak berizin atau status salah'; END IF; SELECT * INTO q FROM public.quotations WHERE id=p_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF q.id IS NULL OR q.converted_order_id IS NOT NULL THEN RAISE EXCEPTION 'Penawaran tidak ditemukan atau terkunci'; END IF; IF p_status IN ('terkirim','disetujui') THEN totals:=public.sales_totals('quotations',q.id); SELECT discount_approval_threshold_pct INTO threshold FROM public.tenant_settings WHERE tenant_id=q.tenant_id; IF (totals->>'effective_discount_pct')::numeric>threshold AND q.approved_fingerprint IS DISTINCT FROM (totals->>'fingerprint') THEN RAISE EXCEPTION 'Diskon belum disetujui'; END IF; IF q.valid_until<(now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Penawaran kedaluwarsa'; END IF; END IF; UPDATE public.quotations SET status=p_status,brand_snapshot=CASE WHEN p_status IN ('terkirim','disetujui') THEN (SELECT to_jsonb(s)||jsonb_build_object('name',t.name) FROM public.tenant_settings s JOIN public.tenants t ON t.id=s.tenant_id WHERE s.tenant_id=q.tenant_id) WHEN p_status='draft' THEN NULL ELSE brand_snapshot END WHERE id=q.id; END $$;